      it("throws if sub-ranges have a gap", () => {
        builder.startRange(0, 0, {
          scopeKey: "test-scope",
          values: [[{
            value: "a",
            from: { line: 0, column: 0 },
            to: { line: 4, column: 0 },
          }, {
            value: "b",
            from: { line: 5, column: 0 },
            to: { line: 10, column: 0 },
          }]],
        });

        assertThrows(() => builder.endRange(10, 0));
      });

      it("throws if a sub-range 'from' does not precede 'to'", () => {
        builder.startRange(0, 0, {
          scopeKey: "test-scope",
          values: [[{
            value: "a",
            from: { line: 5, column: 0 },
            to: { line: 5, column: 0 },
          }]],
        });
        assertThrows(() => builder.endRange(10, 0));

        builder.startRange(0, 0, {
          scopeKey: "test-scope",
          values: [[{
            value: "a",
            from: { line: 6, column: 0 },
            to: { line: 5, column: 0 },
          }]],
        });
        assertThrows(() => builder.endRange(10, 0));
      });
    });
  });
});

