class ItemEncoder {
  #encodedItems: string[] = [];
  #currentItem = "";

  encode(): string {
    const result = this.#encodedItems.join(",");
    this.#encodedItems = [];
    this.#currentItem = "";
    return result;
  }

  finishItem(): this {
    this.#encodedItems.push(this.#currentItem);
    this.#currentItem = "";
    return this;
  }

  addUnsignedVLQs(...ns: number[]): this {
    for (const n of ns) {
      this.#currentItem += encodeUnsigned(n);
    }
    return this;
  }

  addSignedVLQs(...ns: number[]): this {
    for (const n of ns) {
      this.#currentItem += encodeSigned(n);
    }
    return this;
  }
}

function createMap(
  { scopes, ranges, names = [] }: {
    scopes?: (string | null)[];
    ranges?: string | string[];
    names?: string[];
  },
): SourceMapJson {
  return {
    version: 3,
    mappings: "",
    sources: new Array(scopes?.length ?? 0).fill(null),
    scopes,
    ranges: typeof ranges === "string" ? [ranges] : ranges,
    names,
  };
}

describe("decode", () => {
  it("handles unknown items interspersed in an known items", () => {
    const info = new ScopeInfoBuilder().startSource().startScope(0, 0).endScope(
      10,
      0,
    ).endSource()
