      const map: IndexSourceMapJson = {
        version: 3,
        sections: [
          { offset: { line: 0, column: 0 }, map: map1 },
          {
            offset: { line: 1, column: 0 },
            map: nestedIndexMap(2) as unknown as SourceMapJson,
          },
