    });

    it("does not overflow the stack for deeply nested index maps", () => {
      const map = nestedIndexMap(100_000);

      assertEquals(decode(map, { mode: DecodeMode.LAX }).ranges, []);
      assertThrows(
        () => decode(map, { mode: DecodeMode.STRICT }),
