  return result;
})();

for (const { name, mapJson, size } of BENCHMARKS) {
  Deno.bench(`${name}, lax, ${format(size)}`, () => {
    decode(mapJson, { mode: DecodeMode.LAX });
  });

  Deno.bench(`${name}, strict, ${format(size)}`, () => {
    decode(mapJson, { mode: DecodeMode.STRICT });
  });
}

